// Spanish texts of catalog.mjs: [English text, Spanish text], in catalog order. The English side must match the T()
// text exactly (the build names any text without a translation and any entry whose English text changed or went away).
// Terms follow the app (src/Filee.App/Assets/i18n/es.json): ajuste preestablecido (preset), motor (engine), menú circular
// (donut toolbar), carpetas supervisadas (watch folders), zona de suelta (drop zone), preset names as in the app.

import { dictionary } from './dictionary.mjs';

export default dictionary([
  // Engines
  [`video and audio, subtitle extraction and saving HEIC`,
    `vídeo y audio, extracción de subtítulos y guardado en HEIC`],
  [`older office formats such as DOC, PPT and ODT`,
    `formatos de oficina antiguos como DOC, PPT y ODT`],
  [`rare e-book formats and MOBI/AZW3 output`,
    `formatos poco comunes de libros electrónicos y salida en MOBI/AZW3`],
  [`EPS and PostScript`,
    `EPS y PostScript`],
  [`LaTeX, Org, AsciiDoc and other markup, Word → Markdown and Markdown → slides`,
    `LaTeX, Org, AsciiDoc y otros lenguajes de marcado, Word → Markdown y Markdown → diapositivas`],

  // Options
  [`quality`, `calidad`],
  [`Adjustable quality for JPG, WEBP and AVIF: JPG saves at 90 % by default, and a JPG 70 % preset makes smaller files.`,
    `Calidad ajustable para JPG, WEBP y AVIF: JPG se guarda al 90 % de forma predeterminada, y el ajuste preestablecido JPG 70 % genera archivos más pequeños.`],
  [`resize`, `cambio de tamaño`],
  [`Resize while converting, by percentage (for example half size) or to a maximum long edge.`,
    `Cambia el tamaño al convertir, por porcentaje (por ejemplo, a la mitad) o hasta un lado largo máximo.`],
  [`DPI`, `DPI`],
  [`Set the DPI written into the image, for example 300 for print.`,
    `Define los DPI que se guardan en la imagen, por ejemplo 300 para imprimir.`],
  [`grayscale`, `escala de grises`],
  [`A grayscale preset makes black-and-white copies.`,
    `El ajuste preestablecido Grises crea copias en blanco y negro.`],
  [`metadata`, `metadatos`],
  [`Metadata (EXIF, XMP, colour profile) is kept by default and can be removed for privacy.`,
    `Los metadatos (EXIF, XMP, perfil de color) se conservan de forma predeterminada y se pueden quitar por privacidad.`],
  [`ICO sizes`, `tamaños de ICO`],
  [`ICO files hold 256, 128, 64, 48, 32 and 16 px by default; the sizes can be changed in the preset.`,
    `Los archivos ICO incluyen de forma predeterminada 256, 128, 64, 48, 32 y 16 px; los tamaños se pueden cambiar en el ajuste preestablecido.`],
  [`TIFF compression`, `compresión TIFF`],
  [`TIFF compression can be chosen (LZW by default).`,
    `Se puede elegir la compresión TIFF (LZW de forma predeterminada).`],
  [`white background`, `fondo blanco`],
  [`JPG has no transparency, so transparent areas are filled with white.`,
    `JPG no admite transparencia, así que las zonas transparentes se rellenan de blanco.`],
  [`merge into one PDF`, `combinar en un PDF`],
  [`The merge preset combines all dropped files into one PDF.`,
    `El ajuste preestablecido Combinar PDF une todos los archivos soltados en un solo PDF.`],
  [`split pages`, `dividir páginas`],
  [`The split preset saves every page as its own PDF in a subfolder.`,
    `El ajuste preestablecido Dividir PDF guarda cada página como un PDF propio en una subcarpeta.`],
  [`rotate & flip`, `girar y voltear`],
  [`Rotate and flip presets turn images left, right or 180° and mirror them, after the photo's own orientation.`,
    `Los ajustes preestablecidos Rotar y Voltear giran las imágenes a la izquierda, a la derecha o 180° y las reflejan, después de aplicar la orientación propia de la foto.`],
  [`Trace to SVG`, `trazar a SVG`],
  [`Two presets trace a picture into vector shapes: Trace to SVG in up to 64 colours, and Line art to SVG in black for logos, signatures and scans. No other program is needed.`,
    `Dos ajustes preestablecidos trazan una imagen en formas vectoriales: Trazar a SVG, con hasta 64 colores, y Líneas a SVG, en negro para logotipos, firmas y escaneos. No hace falta ningún otro programa.`],
  [`remove background`, `quitar el fondo`],
  [`The Remove background preset makes a plain backdrop transparent: the paper behind a signature or stamp, the backdrop of a logo.`,
    `El ajuste preestablecido Quitar fondo vuelve transparente un fondo liso: el papel detrás de una firma o un sello, o el fondo de un logotipo.`],
  [`page ranges`, `rangos de páginas`],
  [`Page ranges such as 1-3,5 limit the conversion to the pages you need.`,
    `Los rangos de páginas como 1-3,5 limitan la conversión a las páginas que necesitas.`],
  [`render DPI`, `DPI de renderizado`],
  [`Pages are rendered at 150 DPI by default; choose 300 DPI for print quality.`,
    `Las páginas se renderizan a 150 DPI de forma predeterminada; elige 300 DPI para calidad de impresión.`],
  [`one long image`, `una imagen larga`],
  [`The Long image preset stacks all pages into one tall image, e.g. to post a whole document at once.`,
    `El ajuste preestablecido Imagen larga apila todas las páginas en una sola imagen alta, por ejemplo para publicar un documento entero de una vez.`],
  [`compress PDF`, `comprimir PDF`],
  [`The Compress PDF preset makes a PDF smaller while it stays a PDF: pictures are scaled down to 72, 150 or 300 dpi and photos saved again as JPEG, while text, fonts, links, bookmarks and forms stay. A PDF that can't get smaller is left as it was. With Ghostscript installed, Filee can try it too and keep the smaller result.`,
    `El ajuste preestablecido Comprimir PDF reduce el tamaño de un PDF sin que deje de ser PDF: las imágenes se reducen a 72, 150 o 300 ppp y las fotos se vuelven a guardar como JPEG, mientras que el texto, las fuentes, los enlaces, los marcadores y los formularios se mantienen. Un PDF que no se puede reducir se deja como estaba. Con Ghostscript instalado, Filee también puede probar con él y quedarse con el resultado más pequeño.`],
  [`a picture per slide`, `una imagen por diapositiva`],
  [`PPTX (slides) puts a picture of each page on its own slide, at the page's size, with the page's text in the speaker notes. The slides look exactly like the PDF but aren't editable; convert to DOCX for editable text.`,
    `PPTX (diapositivas) coloca una imagen de cada página en su propia diapositiva, con el tamaño de la página, y el texto de la página en las notas del orador. Las diapositivas se ven exactamente como el PDF, pero no se pueden editar; para tener texto editable, convierte a DOCX.`],
  [`vector PDF`, `PDF vectorial`],
  [`The PDF stays vector, so it is sharp at any zoom and in print.`,
    `El PDF sigue siendo vectorial, así que se ve nítido con cualquier zoom y al imprimir.`],
  [`editable`, `editable`],
  [`The result has real text and paragraphs you can edit, not pictures of pages.`,
    `El resultado tiene texto y párrafos reales que puedes editar, no imágenes de las páginas.`],
  [`attachments as ZIP`, `adjuntos en ZIP`],
  [`Attachments can be saved separately as one ZIP.`,
    `Los adjuntos se pueden guardar aparte en un solo ZIP.`],
  [`one CSV per sheet`, `un CSV por hoja`],
  [`Workbooks with several sheets give one CSV per sheet.`,
    `Los libros con varias hojas generan un CSV por hoja.`],
  [`layout kept`, `diseño conservado`],
  [`Keeps page size and margins, headers and footers with page numbers, tables, text boxes, shapes and pictures.`,
    `Conserva el tamaño de página y los márgenes, los encabezados y pies de página con números de página, las tablas, los cuadros de texto, las formas y las imágenes.`],
  [`no Office needed`, `sin Office`],
  [`No Microsoft Office or LibreOffice needed.`,
    `No necesita Microsoft Office ni LibreOffice.`],
  [`no Hancom Office needed`, `sin Hancom Office`],
  [`No Hancom Office and no approval dialog.`,
    `Sin Hancom Office y sin ventana de aprobación.`],
  [`no AutoCAD needed`, `sin AutoCAD`],
  [`No AutoCAD or DWG viewer needed.`,
    `No necesita AutoCAD ni un visor de DWG.`],
  [`no re-encoding`, `sin recodificar`],
  [`When the new format can hold the video and sound as they are (an iPhone MOV → MP4), they are only rewrapped: no quality lost, HDR kept, done in seconds.`,
    `Cuando el formato nuevo puede contener el vídeo y el sonido tal como están (un MOV de iPhone → MP4), solo se cambian de contenedor: sin pérdida de calidad, con HDR conservado y listo en segundos.`],
  [`720p option`, `opción 720p`],
  [`The MP4 720p preset shrinks large videos for sharing.`,
    `El ajuste preestablecido MP4 720p reduce los vídeos grandes para compartirlos.`],
  [`extract audio`, `extraer el audio`],
  [`Only the sound is saved, without the video track.`,
    `Solo se guarda el sonido, sin la pista de vídeo.`],
  [`MP3 128k`, `MP3 128k`],
  [`The MP3 128k preset makes smaller files, ideal for speech.`,
    `El ajuste preestablecido MP3 128k genera archivos más pequeños, ideales para voz.`],
  [`extract`, `extraer`],
  [`The extract preset unpacks an archive into a folder instead.`,
    `El ajuste preestablecido Extraer descomprime el archivo en una carpeta.`],
  [`pack into one ZIP`, `empaquetar en un ZIP`],
  [`Any selection of files can be packed into one ZIP.`,
    `Cualquier selección de archivos se puede empaquetar en un solo ZIP.`],
  [`DRM-free books`, `libros sin DRM`],
  [`Works with DRM-free books only.`,
    `Solo funciona con libros sin DRM.`],
  [`ALAC in M4A`, `ALAC en M4A`],
  [`M4A can hold lossless ALAC as well as AAC.`,
    `M4A puede contener ALAC sin pérdida además de AAC.`],
  [`HEVC / AV1`, `HEVC / AV1`],
  [`Video presets can encode HEVC (H.265) or AV1 for smaller files, keeping 10-bit and HDR video.`,
    `Los ajustes preestablecidos de vídeo pueden codificar en HEVC (H.265) o AV1 para obtener archivos más pequeños, conservando el vídeo de 10 bits y HDR.`],
  [`hardware encoding`, `codificación por hardware`],
  [`Turn on Use hardware acceleration in a video preset to encode H.264 and HEVC on the graphics chip (NVENC, Quick Sync, AMF, VideoToolbox or VA-API): much faster and lighter on power, slightly larger at the same quality. It is off by default, and without a usable chip the video is encoded as before.`,
    `Activa «Usar aceleración por hardware» en un ajuste preestablecido de vídeo para codificar H.264 y HEVC en el chip gráfico (NVENC, Quick Sync, AMF, VideoToolbox o VA-API): mucho más rápido y con menos consumo, aunque algo más grande con la misma calidad. Está desactivado de forma predeterminada y, sin un chip compatible, el vídeo se codifica como siempre.`],
  [`every frame`, `cada fotograma`],
  [`Usually a video gives one still frame. The Extract frames presets, or Save every frame of a video in a PNG or JPG preset, save every frame (or every Nth) as pictures in a folder next to the video.`,
    `Normalmente un vídeo da una sola imagen fija. Los ajustes preestablecidos Extraer fotogramas, o «Guardar cada fotograma de un vídeo» en un ajuste preestablecido PNG o JPG, guardan cada fotograma (o uno de cada N) como imágenes en una carpeta junto al vídeo.`],
  [`extract subtitles`, `extraer subtítulos`],
  [`The Extract subtitles preset on the video donut saves the first text subtitle track of a video as SRT.`,
    `El ajuste preestablecido Extraer subtítulos del menú circular de vídeo guarda la primera pista de subtítulos de texto de un vídeo como SRT.`],
  [`saved as UTF-8`, `guardado en UTF-8`],
  [`Results are saved as UTF-8. Korean files saved in CP949 (EUC-KR) are detected and read correctly.`,
    `Los resultados se guardan en UTF-8. Los archivos coreanos guardados en CP949 (EUC-KR) se detectan y se leen correctamente.`],
  [`tables to CSV / Excel`, `tablas a CSV / Excel`],
  [`Data that is a table (a list of records) also converts to and from CSV and Excel.`,
    `Los datos en forma de tabla (una lista de registros) también se convierten a y desde CSV y Excel.`],
  [`picture preview`, `vista previa en imagen`],
  [`PNG or JPG gives a shaded picture of the model, seen from the front right and above.`,
    `PNG o JPG genera una imagen sombreada del modelo, vista desde delante a la derecha y desde arriba.`],
  [`colours and textures`, `colores y texturas`],
  [`Colours, textures and materials are kept where the target format can hold them. STL keeps only the shape.`,
    `Los colores, las texturas y los materiales se conservan cuando el formato de destino los admite. STL solo guarda la forma.`],
  [`HDR tone-mapped`, `mapeo de tonos HDR`],
  [`HDR screenshots that Windows saves as JPEG XR are tone-mapped to normal brightness instead of being clipped.`,
    `Las capturas de pantalla HDR que Windows guarda como JPEG XR se llevan a un brillo normal con mapeo de tonos, en lugar de recortar las luces.`],
  [`Live Photo video`, `vídeo de Live Photo`],
  [`The Extract Live Photo video preset saves the video of an iPhone Live Photo (a LIVP from iCloud, or a photo with its MOV) or an Android Motion Photo as MP4 or MOV. The other way round, the Live Photo (iPhone) and Motion Photo (Android) presets turn a short clip of a video into a moving photo; that is still experimental.`,
    `El ajuste preestablecido «Extraer vídeo de Live Photo» guarda como MP4 o MOV el vídeo de una Live Photo de iPhone (un LIVP de iCloud o una foto con su MOV) o de una Motion Photo de Android. En sentido contrario, los ajustes preestablecidos «Live Photo (iPhone)» y «Motion Photo (Android)» convierten un fragmento corto de un vídeo en una foto en movimiento; esto todavía es experimental.`],
  [`WGS 84 longitude / latitude`, `longitud / latitud WGS 84`],
  [`Results are always in longitude and latitude (WGS 84). Shapefiles in UTM, Web Mercator, Lambert or Albers are converted, so they open in the right place; converting a file to its own format reprojects it.`,
    `Los resultados siempre están en longitud y latitud (WGS 84). Los Shapefile en UTM, Web Mercator, Lambert o Albers se convierten para que se abran en el lugar correcto; convertir un archivo a su propio formato lo reproyecta.`],
  [`save as ZIP`, `guardar como ZIP`],
  [`A Shapefile is five files (.shp, .shx, .dbf, .prj and .cpg). With Save the result as a ZIP in a preset, or for every geospatial result in the settings, they travel together in one ZIP.`,
    `Un Shapefile son cinco archivos (.shp, .shx, .dbf, .prj y .cpg). Con «Guardar el resultado como ZIP» en un ajuste preestablecido, o con «Guardar todo resultado geoespacial como ZIP» en Ajustes → General, viajan juntos en un solo ZIP.`],

  // Camera RAW
  [`Canon CR2 RAW photo`, `Foto RAW Canon CR2`],
  [`CR2 is the RAW photo format Canon DSLRs used for many years (newer Canon models write CR3). It stores the unprocessed sensor data, which leaves plenty of room for editing.`,
    `CR2 es el formato de foto RAW que las réflex de Canon usaron durante muchos años (los modelos más nuevos escriben CR3). Guarda los datos del sensor sin procesar, lo que deja mucho margen para editar.`],
  [`Nikon NEF RAW photo`, `Foto RAW Nikon NEF`],
  [`NEF is Nikon's RAW photo format, used by Nikon DSLRs and Z mirrorless cameras. Like other RAW files it holds unprocessed sensor data and is several times larger than a JPG.`,
    `NEF es el formato de foto RAW de Nikon, usado por las réflex de Nikon y las cámaras sin espejo Z. Como otros archivos RAW, contiene los datos del sensor sin procesar y ocupa varias veces más que un JPG.`],

  // Images
  [`Images`, `Imágenes`],
  [`images`, `imágenes`],
  [`Photos and graphics, including iPhone HEIC and Live Photos, Photoshop PSD, camera RAW from all major brands, animated APNG, DICOM and the HDR screenshots of Windows (JPEG XR). Resize, rotate, set quality and DPI or strip metadata while converting, or trace a picture into an SVG.`,
    `Fotos y gráficos, incluidos HEIC y Live Photos de iPhone, PSD de Photoshop, RAW de cámara de las principales marcas, APNG animado, DICOM y las capturas HDR de Windows (JPEG XR). Al convertir puedes cambiar el tamaño, girar, ajustar la calidad y los DPI o quitar los metadatos, o trazar una imagen a SVG.`],
  [`JPEG image`, `Imagen JPEG`],
  [`JPEG is the most widely used photo format. Its lossy compression keeps files small, but every save at lower quality discards some detail, and it has no transparency.`,
    `JPEG es el formato de foto más usado. Su compresión con pérdida mantiene los archivos pequeños, pero cada guardado con menor calidad descarta algo de detalle, y no admite transparencia.`],
  [`PNG image`, `Imagen PNG`],
  [`PNG is a lossless image format with transparency, ideal for screenshots, logos and graphics with sharp edges. Photos saved as PNG are usually much larger than JPG.`,
    `PNG es un formato de imagen sin pérdida con transparencia, ideal para capturas de pantalla, logotipos y gráficos con bordes nítidos. Las fotos guardadas en PNG suelen ocupar mucho más que en JPG.`],
  [`WebP image`, `Imagen WebP`],
  [`WebP is Google's image format for the web. It supports lossy and lossless compression and transparency and is usually smaller than JPG or PNG, but some editors and upload forms still don't accept it.`,
    `WebP es el formato de imagen de Google para la web. Admite compresión con y sin pérdida y transparencia, y suele ocupar menos que JPG o PNG, pero algunos editores y formularios de subida todavía no lo aceptan.`],
  [`AVIF image`, `Imagen AVIF`],
  [`AVIF is a modern image format based on the AV1 video codec. It compresses better than JPG and WebP, but support in older software and devices is still limited.`,
    `AVIF es un formato de imagen moderno basado en el códec de vídeo AV1. Comprime mejor que JPG y WebP, pero el soporte en programas y dispositivos antiguos aún es limitado.`],
  [`HEIC / HEIF image`, `Imagen HEIC / HEIF`],
  [`HEIC (HEIF) is the photo format iPhones and iPads use by default. Photos are often about half the size of a JPG, but many Windows apps, websites and older devices can't open them.`,
    `HEIC (HEIF) es el formato de foto que usan de forma predeterminada el iPhone y el iPad. Las fotos suelen ocupar la mitad que un JPG, pero muchas aplicaciones de Windows, sitios web y dispositivos antiguos no pueden abrirlas.`],
  [`GIF image / animation`, `Imagen / animación GIF`],
  [`GIF is an old image format limited to 256 colours that supports simple animation. It is still the universal way to share short silent loops in chats, documents and bug reports.`,
    `GIF es un formato de imagen antiguo limitado a 256 colores que admite animaciones sencillas. Sigue siendo la forma universal de compartir bucles cortos sin sonido en chats, documentos e informes de errores.`],
  [`Windows icon`, `Icono de Windows`],
  [`ICO is the Windows icon format. One ICO file holds the same picture at several sizes (for example 16, 32, 48 and 256 pixels), so it looks sharp everywhere from the taskbar to website favicons.`,
    `ICO es el formato de iconos de Windows. Un archivo ICO contiene la misma imagen en varios tamaños (por ejemplo, 16, 32, 48 y 256 píxeles), así que se ve nítido en todas partes, desde la barra de tareas hasta los favicons de los sitios web.`],
  [`Photoshop document`, `Documento de Photoshop`],
  [`PSD is Adobe Photoshop's native format. It keeps layers, masks and adjustment settings, so it is great for editing but can't be opened by most viewers or websites.`,
    `PSD es el formato nativo de Adobe Photoshop. Conserva capas, máscaras y ajustes, por lo que es ideal para editar, pero la mayoría de visores y sitios web no pueden abrirlo.`],
  [`macOS icon`, `Icono de macOS`],
  [`ICNS is the icon format of macOS. Like ICO it bundles several sizes of one image, up to 1024×1024 for Retina displays, and is used for app icons on the Mac.`,
    `ICNS es el formato de iconos de macOS. Como ICO, agrupa varios tamaños de una imagen, hasta 1024×1024 para pantallas Retina, y se usa para los iconos de las apps en el Mac.`],
  [`Camera RAW`, `RAW de cámara`],
  [`Windows only`, `solo en Windows`],
  [`the photo of the Live Photo`, `la foto de la Live Photo`],
  [`the video of the Live Photo`, `el vídeo de la Live Photo`],

  // Vector graphics
  [`Vector graphics`, `Gráficos vectoriales`],
  [`vector graphics`, `gráficos vectoriales`],
  [`SVG, Windows metafiles, Illustrator, EPS/PostScript and drawings from CorelDRAW, Visio and LibreOffice Draw. SVG also becomes DXF or DWG for CAD.`,
    `SVG, metarchivos de Windows, Illustrator, EPS/PostScript y dibujos de CorelDRAW, Visio y LibreOffice Draw. SVG también se convierte en DXF o DWG para CAD.`],
  [`SVG vector graphic`, `Gráfico vectorial SVG`],
  [`SVG is an XML-based vector graphics format. Shapes and text stay sharp at any size, which makes it ideal for logos and icons on the web, but many apps and upload forms only accept pixel images.`,
    `SVG es un formato de gráficos vectoriales basado en XML. Las formas y el texto se mantienen nítidos a cualquier tamaño, lo que lo hace ideal para logotipos e iconos en la web, pero muchas aplicaciones y formularios de subida solo aceptan imágenes de píxeles.`],
  [`Encapsulated PostScript`, `Encapsulated PostScript`],
  [`EPS is a vector format from print and design work, often used for logos and illustrations sent to print shops. Most modern apps can't show it without a PostScript interpreter.`,
    `EPS es un formato vectorial del mundo de la impresión y el diseño, muy usado para logotipos e ilustraciones que se envían a imprentas. La mayoría de las aplicaciones modernas no pueden mostrarlo sin un intérprete de PostScript.`],
  [`AI files saved with PDF content (Illustrator's default)`,
    `archivos AI guardados con contenido PDF (la opción predeterminada de Illustrator)`],

  // PDF
  [`PDF`, `PDF`],
  [`Turn PDFs into images, editable Word or HWPX documents, PowerPoint slides, text or a comic archive, and merge, split, compress or pick pages.`,
    `Convierte PDF en imágenes, documentos editables de Word o HWPX, diapositivas de PowerPoint, texto o un archivo de cómic, y combina, divide, comprime o elige páginas.`],
  [`PDF document`, `Documento PDF`],
  [`PDF is the standard for sharing documents that must look the same everywhere. Fonts, layout and images are fixed, and it opens on any device. That also makes PDFs hard to edit.`,
    `PDF es el estándar para compartir documentos que deben verse igual en todas partes. Las fuentes, el diseño y las imágenes son fijos, y se abre en cualquier dispositivo. Por eso mismo los PDF son difíciles de editar.`],
  [`one page`, `una página`],

  // Documents
  [`Documents`, `Documentos`],
  [`documents`, `documentos`],
  [`Word documents without Microsoft Office, Chinese OFD e-invoices, older and rare word-processor formats with the optional LibreOffice engine, and saved e-mails (EML and Outlook MSG).`,
    `Documentos de Word sin Microsoft Office, facturas electrónicas chinas OFD, formatos de procesadores de texto antiguos y poco comunes con el motor opcional LibreOffice, y correos electrónicos guardados (EML y Outlook MSG).`],
  [`Word document`, `Documento de Word`],
  [`DOCX is the Microsoft Word format since Word 2007 (Office Open XML). It is the most common format for editable documents such as reports, letters and forms.`,
    `DOCX es el formato de Microsoft Word desde Word 2007 (Office Open XML). Es el formato más habitual para documentos editables como informes, cartas y formularios.`],
  [`Word 97–2003 document`, `Documento de Word 97–2003`],
  [`DOC is the binary format of Word 97–2003. Old archives, official forms and legacy systems still produce it, but it is being replaced by DOCX.`,
    `DOC es el formato binario de Word 97–2003. Los archivos antiguos, los formularios oficiales y los sistemas heredados todavía lo generan, pero está siendo sustituido por DOCX.`],
  [`E-mail message`, `Mensaje de correo electrónico`],
  [`EML is a single e-mail saved as a file (MIME format), with the headers, the message and its attachments. Most mail apps, including Outlook and Thunderbird, can open it.`,
    `EML es un único correo electrónico guardado como archivo (formato MIME), con los encabezados, el mensaje y sus adjuntos. La mayoría de las aplicaciones de correo, incluidos Outlook y Thunderbird, pueden abrirlo.`],
  [`Outlook message`, `Mensaje de Outlook`],
  [`MSG is the file Microsoft Outlook saves when you drag an e-mail out of it. Only Outlook opens it, so it is hard to read on a PC without Outlook or on a phone.`,
    `MSG es el archivo que guarda Microsoft Outlook cuando arrastras un correo fuera de él. Solo Outlook lo abre, así que es difícil leerlo en un PC sin Outlook o en el móvil.`],

  // HWP
  [`HWP (Hangul)`, `HWP (Hangul)`],
  [`Korean HWP/HWPX`, `HWP/HWPX coreanos`],
  [`Korean Hancom Hangul documents without Hancom Office: HWP ↔ HWPX, to PDF, images, Word, text, Markdown and HTML, and HWPX from Word, Excel, PowerPoint, Markdown and PDF.`,
    `Documentos coreanos de Hancom Hangul sin Hancom Office: HWP ↔ HWPX, a PDF, imágenes, Word, texto, Markdown y HTML, y HWPX a partir de Word, Excel, PowerPoint, Markdown y PDF.`],
  [`Hangul document (HWP)`, `Documento de Hangul (HWP)`],
  [`HWP is the document format of Hancom Office Hangul (한글), the standard word processor in Korean government offices, schools and many companies. Outside Korea few programs can open it.`,
    `HWP es el formato de documentos de Hancom Office Hangul (한글), el procesador de texto estándar en la administración pública, las escuelas y muchas empresas de Corea. Fuera de Corea, pocos programas pueden abrirlo.`],
  [`Hangul document (HWPX)`, `Documento de Hangul (HWPX)`],
  [`HWPX is the open, XML-based format of Hancom Hangul (OWPML, Korean national standard KS X 6101). Korean public institutions are moving to it from the binary HWP format.`,
    `HWPX es el formato abierto basado en XML de Hancom Hangul (OWPML, norma nacional coreana KS X 6101). Las instituciones públicas coreanas están pasando a él desde el formato binario HWP.`],

  // Spreadsheets
  [`Spreadsheets`, `Hojas de cálculo`],
  [`spreadsheets`, `hojas de cálculo`],
  [`Excel, OpenDocument and CSV/TSV sheets, to PDF with Excel-like page fitting or into each other, without Excel.`,
    `Hojas de Excel, OpenDocument y CSV/TSV, a PDF con ajuste de página como en Excel o entre sí, sin Excel.`],
  [`Excel workbook`, `Libro de Excel`],
  [`XLSX is the Microsoft Excel workbook format since Excel 2007. One workbook can hold several sheets with formulas, formatting, charts and pictures.`,
    `XLSX es el formato de libro de Microsoft Excel desde Excel 2007. Un libro puede contener varias hojas con fórmulas, formato, gráficos e imágenes.`],
  [`Excel 97–2003 workbook`, `Libro de Excel 97–2003`],
  [`XLS is the binary workbook format of Excel 97–2003. Many older systems and bank or accounting exports still produce it.`,
    `XLS es el formato binario de libro de Excel 97–2003. Muchos sistemas antiguos y exportaciones de bancos o programas de contabilidad todavía lo generan.`],
  [`Comma-separated values`, `Valores separados por comas`],
  [`CSV is plain text with one table row per line. Every spreadsheet, database and programming language reads it, but it has no formatting, formulas or multiple sheets.`,
    `CSV es texto sin formato con una fila de tabla por línea. Cualquier hoja de cálculo, base de datos o lenguaje de programación lo lee, pero no admite formato, fórmulas ni varias hojas.`],

  // Presentations
  [`Presentations`, `Presentaciones`],
  [`presentations`, `presentaciones`],
  [`PowerPoint to PDF, images and HWPX without PowerPoint; older PPT, ODP and Keynote with the optional LibreOffice engine.`,
    `PowerPoint a PDF, imágenes y HWPX sin PowerPoint; PPT antiguos, ODP y Keynote con el motor opcional LibreOffice.`],
  [`PowerPoint presentation`, `Presentación de PowerPoint`],
  [`PPTX is the Microsoft PowerPoint format since PowerPoint 2007. It holds slides with text, pictures, shapes, tables, notes and animations.`,
    `PPTX es el formato de Microsoft PowerPoint desde PowerPoint 2007. Contiene diapositivas con texto, imágenes, formas, tablas, notas y animaciones.`],
  [`PowerPoint 97–2003 presentation`, `Presentación de PowerPoint 97–2003`],
  [`PPT is the binary format of PowerPoint 97–2003. Old lecture slides and archived presentations are often still in PPT.`,
    `PPT es el formato binario de PowerPoint 97–2003. Las diapositivas de clases antiguas y las presentaciones archivadas suelen estar todavía en PPT.`],

  // Text & markup
  [`Text & markup`, `Texto y marcado`],
  [`text and markup`, `texto y marcado`],
  [`Plain text, Markdown, HTML and saved web pages (MHTML) to PDF, Word, HWPX and EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter and other markup use the optional Pandoc engine, which also turns Markdown into PowerPoint slides.`,
    `Texto sin formato, Markdown, HTML y páginas web guardadas (MHTML) a PDF, Word, HWPX y EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter y otros lenguajes de marcado usan el motor opcional Pandoc, que también convierte Markdown en diapositivas de PowerPoint.`],
  [`Plain text`, `Texto sin formato`],
  [`TXT is plain text without any formatting, the simplest and most portable document format. The only thing that can differ is the character encoding (UTF-8, UTF-16 or a legacy code page).`,
    `TXT es texto sin ningún formato, el formato de documento más sencillo y portátil. Lo único que puede variar es la codificación de caracteres (UTF-8, UTF-16 o una página de códigos antigua).`],
  [`Markdown`, `Markdown`],
  [`Markdown is a lightweight plain-text markup: # for headings, * for lists, ** for bold. It is popular for notes, README files and documentation, and is readable even without rendering.`,
    `Markdown es un lenguaje de marcado ligero en texto sin formato: # para títulos, * para listas, ** para negrita. Es muy usado en notas, archivos README y documentación, y se lee bien incluso sin renderizar.`],
  [`Web page (HTML)`, `Página web (HTML)`],
  [`HTML is the language of web pages. A saved .html file opens in any browser, but how it looks depends on the browser and on linked styles and images, which may be missing offline.`,
    `HTML es el lenguaje de las páginas web. Un archivo .html guardado se abre en cualquier navegador, pero su aspecto depende del navegador y de los estilos e imágenes enlazados, que pueden faltar sin conexión.`],
  [`LOG files and scripts (PY, PAC, BAT, COMMAND) are read as text and never run`,
    `los archivos LOG y los scripts (PY, PAC, BAT, COMMAND) se leen como texto y nunca se ejecutan`],
  [`the saved page, with its pictures`, `la página guardada, con sus imágenes`],

  // Data
  [`Data`, `Datos`],
  [`data files`, `archivos de datos`],
  [`JSON, JSON Lines, YAML, TOML and XML into each other, and tables to and from CSV and Excel. vCard contacts to and from CSV, also from old phones. Nothing to install.`,
    `JSON, JSON Lines, YAML, TOML y XML entre sí, y tablas a y desde CSV y Excel. Contactos vCard a y desde CSV, también de móviles antiguos. No hay nada que instalar.`],
  [`JSON data`, `Datos JSON`],
  [`JSON is the data format of the web: objects, lists, text and numbers in plain text. APIs, apps and settings files use it everywhere.`,
    `JSON es el formato de datos de la web: objetos, listas, texto y números en texto sin formato. Lo usan en todas partes las API, las aplicaciones y los archivos de configuración.`],
  [`YAML data`, `Datos YAML`],
  [`YAML holds the same kind of data as JSON, written with indentation instead of brackets. Config files for Docker, Kubernetes, CI pipelines and many apps are YAML.`,
    `YAML guarda el mismo tipo de datos que JSON, escritos con sangría en lugar de llaves y corchetes. Los archivos de configuración de Docker, Kubernetes, las canalizaciones de CI y muchas aplicaciones están en YAML.`],
  [`vCard contacts`, `Contactos vCard`],
  [`vCard (.vcf) is the standard file for contacts. Phones, Outlook, Google Contacts and iCloud export address books as vCard, often many contacts in one file.`,
    `vCard (.vcf) es el archivo estándar para contactos. Los móviles, Outlook, Google Contactos e iCloud exportan las libretas de direcciones como vCard, a menudo con muchos contactos en un solo archivo.`],

  // E-books & comics
  [`E-books & comics`, `Libros electrónicos y cómics`],
  [`e-books and comics`, `libros electrónicos y cómics`],
  [`EPUB, Kindle (MOBI, AZW, AZW3), FictionBook and comic archives (CBZ, CBR, CB7…) to PDF, EPUB, Word and more, and KEPUB for Kobo readers. DRM-free books only.`,
    `EPUB, Kindle (MOBI, AZW, AZW3), FictionBook y archivos de cómic (CBZ, CBR, CB7…) a PDF, EPUB, Word y más, y KEPUB para lectores Kobo. Solo libros sin DRM.`],
  [`EPUB e-book`, `Libro electrónico EPUB`],
  [`EPUB is the open standard for e-books. Text reflows to fit any screen, and most e-readers and reading apps support it; Kindle accepts EPUB through Send to Kindle.`,
    `EPUB es el estándar abierto de los libros electrónicos. El texto se adapta a cualquier pantalla y la mayoría de lectores y apps de lectura lo admiten; Kindle acepta EPUB mediante Send to Kindle.`],
  [`Kindle / Mobipocket e-book`, `Libro electrónico Kindle / Mobipocket`],
  [`MOBI is the older Mobipocket e-book format that Amazon Kindle used for years. It is still common in older e-book collections, but Amazon has moved to AZW3/KFX and EPUB.`,
    `MOBI es el antiguo formato de libro electrónico Mobipocket que Amazon Kindle usó durante años. Sigue siendo habitual en colecciones antiguas, pero Amazon ha pasado a AZW3/KFX y EPUB.`],

  // Video
  [`Video`, `Vídeo`],
  [`video`, `vídeo`],
  [`All common video formats to MP4 (H.264, HEVC or AV1), WebM, MOV, MKV, AVI, GIF or APNG, with a 720p option, hardware encoding on the graphics chip, audio extraction to MP3 or M4A and every frame saved as pictures. Uses the optional FFmpeg engine.`,
    `Todos los formatos de vídeo habituales a MP4 (H.264, HEVC o AV1), WebM, MOV, MKV, AVI, GIF o APNG, con opción de 720p, codificación por hardware en el chip gráfico, extracción del audio a MP3 o M4A y cada fotograma guardado como imagen. Usa el motor opcional FFmpeg.`],
  [`MPEG-4 video`, `Vídeo MPEG-4`],
  [`MP4 (MPEG-4 Part 14) is the most compatible video format. It plays on phones, TVs, browsers and every video site, usually with H.264 or H.265 video and AAC audio.`,
    `MP4 (MPEG-4 Parte 14) es el formato de vídeo más compatible. Se reproduce en móviles, televisores, navegadores y en cualquier web de vídeos, normalmente con vídeo H.264 o H.265 y audio AAC.`],
  [`QuickTime movie`, `Vídeo QuickTime`],
  [`MOV is Apple's QuickTime video format, used by iPhones and Macs. It usually contains H.264 or HEVC video, but some editors, TVs and websites handle MP4 better.`,
    `MOV es el formato de vídeo QuickTime de Apple, que usan el iPhone y el Mac. Suele contener vídeo H.264 o HEVC, pero algunos editores, televisores y sitios web funcionan mejor con MP4.`],
  [`Matroska video`, `Vídeo Matroska`],
  [`MKV (Matroska) is a flexible open container that can hold many video, audio and subtitle tracks. It is popular for films and recordings, but phones, TVs and editors don't always play it.`,
    `MKV (Matroska) es un contenedor abierto y flexible que puede contener muchas pistas de vídeo, audio y subtítulos. Es popular para películas y grabaciones, pero los móviles, los televisores y los editores no siempre lo reproducen.`],
  [`WebM video`, `Vídeo WebM`],
  [`WebM is an open video format made for browsers (VP8/VP9 or AV1 video with Vorbis or Opus audio). Screen recordings and downloads are often WebM, but many editors and devices expect MP4.`,
    `WebM es un formato de vídeo abierto pensado para navegadores (vídeo VP8/VP9 o AV1 con audio Vorbis u Opus). Las grabaciones de pantalla y las descargas suelen ser WebM, pero muchos editores y dispositivos esperan MP4.`],
  [`AVI video`, `Vídeo AVI`],
  [`AVI is Microsoft's video container from the 1990s. Camcorders, older cameras and archives still hold AVI files, which are often large and poorly supported on phones.`,
    `AVI es el contenedor de vídeo de Microsoft de los años noventa. Las videocámaras, las cámaras antiguas y los archivos guardan todavía ficheros AVI, que suelen ser grandes y se reproducen mal en los móviles.`],
  [`one still frame or every frame`, `una imagen fija o cada fotograma`],

  // Audio
  [`Audio`, `Audio`],
  [`audio`, `audio`],
  [`Music, recordings and voice memos to MP3, M4A, WAV, FLAC, OGG, Opus, AAC or lossless WavPack and TTA. APE, DSD and DTS are read too. Uses the optional FFmpeg engine.`,
    `Música, grabaciones y notas de voz a MP3, M4A, WAV, FLAC, OGG, Opus, AAC o WavPack y TTA sin pérdida. También lee APE, DSD y DTS. Usa el motor opcional FFmpeg.`],
  [`MP3 audio`, `Audio MP3`],
  [`MP3 is the classic compressed audio format. Practically every player, car stereo and phone plays it, which makes it the safest choice for sharing music, podcasts and recordings.`,
    `MP3 es el formato de audio comprimido clásico. Prácticamente cualquier reproductor, autorradio o móvil lo reproduce, por lo que es la opción más segura para compartir música, pódcasts y grabaciones.`],
  [`MPEG-4 audio`, `Audio MPEG-4`],
  [`M4A is an MPEG-4 audio file, usually AAC, used by iTunes, iPhone voice memos and many recorders. It sounds good at small sizes, but some players and car stereos only take MP3.`,
    `M4A es un archivo de audio MPEG-4, normalmente AAC, que usan iTunes, las notas de voz del iPhone y muchas grabadoras. Suena bien con poco tamaño, pero algunos reproductores y autorradios solo aceptan MP3.`],
  [`WAV audio`, `Audio WAV`],
  [`WAV is uncompressed audio (usually PCM) used for recording and editing. It sounds exactly like the source but takes about 10 MB per minute in CD quality.`,
    `WAV es audio sin comprimir (normalmente PCM) que se usa para grabar y editar. Suena exactamente como el original, pero ocupa unos 10 MB por minuto con calidad de CD.`],
  [`FLAC lossless audio`, `Audio sin pérdida FLAC`],
  [`FLAC is lossless compressed audio: it shrinks files to roughly half the size of WAV without losing any quality, which makes it the favourite format for music libraries and hi-res downloads.`,
    `FLAC es audio comprimido sin pérdida: reduce los archivos a aproximadamente la mitad que un WAV sin perder calidad, por eso es el formato favorito para bibliotecas musicales y descargas de alta resolución.`],

  // Subtitles
  [`Subtitles`, `Subtítulos`],
  [`subtitles`, `subtítulos`],
  [`SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML and MicroDVD into each other without any engine, saved as UTF-8; SSA and SCC are read. Korean SMI and SRT files in CP949 are read correctly. Subtitles in a video come out with FFmpeg.`,
    `SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML y MicroDVD entre sí sin ningún motor, guardados en UTF-8; también lee SSA y SCC. Los archivos SMI y SRT coreanos en CP949 se leen correctamente. Los subtítulos de un vídeo se extraen con FFmpeg.`],
  [`SubRip subtitles`, `Subtítulos SubRip`],
  [`SRT (SubRip) is the most common subtitle file: numbered cues with start and end times and plain text. Nearly every player, editor and video site accepts it.`,
    `SRT (SubRip) es el archivo de subtítulos más habitual: entradas numeradas con hora de inicio y de fin y texto sin formato. Casi cualquier reproductor, editor y web de vídeos lo acepta.`],
  [`Advanced SubStation Alpha subtitles`, `Subtítulos Advanced SubStation Alpha`],
  [`ASS (Advanced SubStation Alpha) is the styled subtitle format of anime fansubs and Aegisub, with fonts, colours, positions and effects. Many devices and sites only take plain SRT.`,
    `ASS (Advanced SubStation Alpha) es el formato de subtítulos con estilos de los fansubs de anime y de Aegisub, con fuentes, colores, posiciones y efectos. Muchos dispositivos y webs solo aceptan SRT sencillo.`],
  [`WebVTT subtitles`, `Subtítulos WebVTT`],
  [`WebVTT (.vtt) is the subtitle format of HTML5 video. Web players, YouTube and online course platforms use it.`,
    `WebVTT (.vtt) es el formato de subtítulos del vídeo HTML5. Lo usan los reproductores web, YouTube y las plataformas de cursos en línea.`],
  [`SAMI subtitles (SMI)`, `Subtítulos SAMI (SMI)`],
  [`SAMI (.smi) is Microsoft's HTML-like subtitle format. It is still the classic subtitle file in Korea, often saved in the old CP949 encoding that newer players show as broken text.`,
    `SAMI (.smi) es el formato de subtítulos de Microsoft, parecido a HTML. En Corea sigue siendo el archivo de subtítulos clásico, a menudo guardado en la antigua codificación CP949, que los reproductores modernos muestran como texto ilegible.`],

  // Archives
  [`Archives`, `Archivos comprimidos`],
  [`archives`, `archivos comprimidos`],
  [`Repack or extract ZIP, 7Z, RAR, TAR, disk images and many more archive formats with the bundled 7-Zip engine, or pack any files into one ZIP.`,
    `Vuelve a empaquetar o extrae ZIP, 7Z, RAR, TAR, imágenes de disco y muchos otros formatos comprimidos con el motor 7-Zip incluido, o empaqueta cualquier archivo en un solo ZIP.`],
  [`ZIP archive`, `Archivo ZIP`],
  [`ZIP is the universal archive format. Windows, macOS, phones and nearly every upload form open it without extra software.`,
    `ZIP es el formato comprimido universal. Windows, macOS, los móviles y casi cualquier formulario de subida lo abren sin software adicional.`],
  [`7-Zip archive`, `Archivo 7-Zip`],
  [`7Z is the open archive format of 7-Zip. Its LZMA2 compression usually makes smaller files than ZIP, but not every system or website can open it.`,
    `7Z es el formato comprimido abierto de 7-Zip. Su compresión LZMA2 suele generar archivos más pequeños que ZIP, pero no todos los sistemas ni sitios web pueden abrirlo.`],
  [`RAR archive`, `Archivo RAR`],
  [`RAR is the proprietary archive format of WinRAR, common for downloads split into parts. Recent Windows 11 versions can open RAR but can't create it, and many tools only accept ZIP.`,
    `RAR es el formato comprimido propietario de WinRAR, habitual en descargas divididas en partes. Las versiones recientes de Windows 11 pueden abrir RAR pero no crearlo, y muchas herramientas solo aceptan ZIP.`],
  [`Any files`, `Cualquier archivo`],

  // CAD drawings
  [`CAD drawings`, `Planos CAD`],
  [`CAD drawings [in running text]`, `planos CAD`],
  [`AutoCAD DWG and DXF: convert between them or to PDF, SVG and PNG, without AutoCAD.`,
    `DWG y DXF de AutoCAD: convierte entre ellos o a PDF, SVG y PNG, sin AutoCAD.`],
  [`AutoCAD drawing`, `Plano de AutoCAD`],
  [`DWG is AutoCAD's native drawing format and the most common CAD file in architecture and engineering. Without AutoCAD or a DWG viewer it is hard to open or share.`,
    `DWG es el formato de plano nativo de AutoCAD y el archivo CAD más común en arquitectura e ingeniería. Sin AutoCAD o un visor de DWG es difícil abrirlo o compartirlo.`],
  [`Drawing Exchange Format`, `Drawing Exchange Format`],
  [`DXF (Drawing Exchange Format) is Autodesk's interchange format for CAD drawings. Laser cutters, CNC software and most CAD programs read it, so it is the usual way to move drawings between tools.`,
    `DXF (Drawing Exchange Format) es el formato de intercambio de Autodesk para planos CAD. Lo leen las cortadoras láser, el software CNC y la mayoría de los programas CAD, por lo que es la forma habitual de pasar planos entre herramientas.`],

  // 3D models
  [`3D models`, `Modelos 3D`],
  [`3D models [in running text]`, `modelos 3D`],
  [`GLB, glTF, STL, OBJ, 3MF and PLY into each other, and FBX into any of them, with colours, textures and materials where the format keeps them, and to a shaded PNG or JPG picture. Nothing to install.`,
    `GLB, glTF, STL, OBJ, 3MF y PLY entre sí, y FBX a cualquiera de ellos, con colores, texturas y materiales cuando el formato los conserva, y a una imagen sombreada en PNG o JPG. No hay nada que instalar.`],
  [`glTF binary (GLB)`, `glTF binario (GLB)`],
  [`GLB is the one-file version of glTF, the 3D format of the web, AR and game engines. Meshes, materials and textures are packed into a single compact file.`,
    `GLB es la versión en un solo archivo de glTF, el formato 3D de la web, la realidad aumentada y los motores de videojuegos. Las mallas, los materiales y las texturas van en un único archivo compacto.`],
  [`STL 3D model`, `Modelo 3D STL`],
  [`STL is the classic file for 3D printing. It stores only the triangles of a shape, with no colours or units, and every slicer and CAD program reads it.`,
    `STL es el archivo clásico de la impresión 3D. Solo guarda los triángulos de una forma, sin colores ni unidades, y lo lee cualquier laminador y programa CAD.`],
  [`Wavefront OBJ model`, `Modelo Wavefront OBJ`],
  [`OBJ (Wavefront) is a plain-text 3D format almost every 3D program opens. Materials and textures sit next to it in an .mtl file and pictures.`,
    `OBJ (Wavefront) es un formato 3D en texto sin formato que abre casi cualquier programa 3D. Los materiales y las texturas van al lado, en un archivo .mtl y en imágenes.`],

  // Fonts
  [`Fonts`, `Tipografías`],
  [`fonts`, `tipografías`],
  [`Desktop and web fonts: TTF, OTF, WOFF, WOFF2 and EOT into each other.`,
    `Tipografías de escritorio y web: TTF, OTF, WOFF, WOFF2 y EOT entre sí.`],
  [`TrueType font`, `Tipografía TrueType`],
  [`TTF (TrueType) is the most common desktop font format on Windows and macOS. Install it to use the font in any app.`,
    `TTF (TrueType) es el formato de tipografías de escritorio más común en Windows y macOS. Instálala para usarla en cualquier aplicación.`],
  [`OpenType font`, `Tipografía OpenType`],
  [`OTF (OpenType) is a font format by Adobe and Microsoft. OpenType fonts with PostScript (CFF) outlines are common for professional typefaces and support features such as ligatures.`,
    `OTF (OpenType) es un formato de tipografías de Adobe y Microsoft. Las tipografías OpenType con contornos PostScript (CFF) son habituales en familias profesionales y admiten funciones como las ligaduras.`],
  [`Web font (WOFF2)`, `Tipografía web (WOFF2)`],
  [`WOFF2 is the compressed web font format supported by all modern browsers. It is typically about 30 % smaller than WOFF, so pages load faster.`,
    `WOFF2 es el formato comprimido de tipografías web compatible con todos los navegadores modernos. Suele ocupar un 30 % menos que WOFF, así que las páginas cargan más rápido.`],

  // Geospatial data
  [`Geospatial data`, `Datos geoespaciales`],
  [`geospatial data`, `datos geoespaciales`],
  [`Maps and GPS data: GeoJSON, KML, KMZ, GPX and Shapefile into each other and to CSV, Excel and JSON, and a CSV with coordinates back into a map file. Vector data only (points, lines and areas), always saved in longitude and latitude. Nothing to install.`,
    `Mapas y datos GPS: GeoJSON, KML, KMZ, GPX y Shapefile entre sí y a CSV, Excel y JSON, y un CSV con coordenadas de vuelta a un archivo de mapa. Solo datos vectoriales (puntos, líneas y áreas), siempre guardados en longitud y latitud. No hay nada que instalar.`],
  [`one row per feature, with its coordinates`, `una fila por elemento, con sus coordenadas`],
  [`a CSV with longitude and latitude columns or WKT`, `un CSV con columnas de longitud y latitud o WKT`],

  // Camera RAW group (conversion pages)
  [`Camera RAW photo`, `Foto RAW de cámara`],
  [`Camera RAW files (CR2, CR3, NEF, ARW, DNG, RAF, ORF and more) hold the unprocessed sensor data of a photo. They keep the most detail for editing but are large and need special software to view.`,
    `Los archivos RAW de cámara (CR2, CR3, NEF, ARW, DNG, RAF, ORF y más) contienen los datos del sensor sin procesar de una foto. Conservan el máximo detalle para editar, pero son grandes y necesitan software especial para verlos.`],

  // Conversion guides: images
  [`JPG is the safe choice when a website, an older Windows app or someone without an iPhone needs your photos. A whole batch of HEIC photos converts at once, and each JPG is saved next to its original.`,
    `JPG es la opción segura cuando una web, una aplicación antigua de Windows o alguien sin iPhone necesita tus fotos. Un lote entero de fotos HEIC se convierte de una vez, y cada JPG se guarda junto a su original.`],
  [`Choose PNG when you want to keep editing the photo without adding a round of JPG compression. PNG is lossless, so expect files several times larger than the HEIC original.`,
    `Elige PNG si quieres seguir editando la foto sin añadir otra ronda de compresión JPG. PNG no tiene pérdida, así que los archivos ocuparán varias veces más que el HEIC original.`],
  [`HEIC keeps a photo in about half the space of a JPG at the same quality, the way iPhones save photos. Saving HEIC needs the free FFmpeg engine (about 100 MB, downloaded once in the app). EXIF, the colour profile and the orientation are kept.`,
    `HEIC guarda una foto en aproximadamente la mitad de espacio que un JPG con la misma calidad, como hace el iPhone. Para guardar en HEIC hace falta el motor gratuito FFmpeg (unos 100 MB, se descarga una vez en la aplicación). Se conservan el EXIF, el perfil de color y la orientación.`],
  [`Images saved from websites are often WebP. Converting to PNG keeps the full quality and any transparency, so the result works in every editor, slide deck and document.`,
    `Las imágenes guardadas de sitios web suelen ser WebP. Al convertirlas a PNG se conserva toda la calidad y la transparencia, así que el resultado funciona en cualquier editor, presentación y documento.`],
  [`Pick JPG when the image is a photo and file size matters, for example for upload forms that reject WebP.`,
    `Elige JPG cuando la imagen es una foto y el tamaño importa, por ejemplo para formularios de subida que rechazan WebP.`],
  [`Screenshots and exported photos saved as PNG can be many megabytes. Photos usually get much smaller as JPG; for text-heavy screenshots and logos, PNG often stays the better format.`,
    `Las capturas de pantalla y las fotos exportadas en PNG pueden ocupar muchos megas. Las fotos suelen quedar mucho más pequeñas en JPG; para capturas con mucho texto y logotipos, PNG sigue siendo a menudo el mejor formato.`],
  [`Converting JPG to PNG doesn't bring back detail lost to JPG compression, but it stops further loss: every later edit and save stays lossless. Convert before you retouch an image or add transparency in an editor.`,
    `Convertir JPG a PNG no recupera el detalle perdido por la compresión JPG, pero evita más pérdidas: cada edición y cada guardado posteriores serán sin pérdida. Conviértela antes de retocar una imagen o de añadirle transparencia en un editor.`],
  [`AVIF images from modern websites and phones don't open in many older programs, image viewers and upload forms. JPG opens everywhere, at the cost of somewhat larger files.`,
    `Las imágenes AVIF de webs y móviles modernos no se abren en muchos programas antiguos, visores de imágenes y formularios de subida. JPG se abre en todas partes, a cambio de archivos algo más grandes.`],
  [`WebP is ideal for websites: photos get much smaller than JPG and graphics keep their transparency. The WEBP preset saves at quality 85, a good balance for the web.`,
    `WebP es ideal para sitios web: las fotos ocupan mucho menos que en JPG y los gráficos conservan la transparencia. El ajuste preestablecido WEBP guarda con calidad 85, un buen equilibrio para la web.`],
  [`Scanned pages, receipts and photos of documents often have to be sent as one PDF. Drop the images on the merge preset to get a single PDF, or on PDF to get one PDF per image. By default each page takes the size of its image.`,
    `Las páginas escaneadas, los recibos y las fotos de documentos a menudo hay que enviarlos como un solo PDF. Suelta las imágenes sobre el ajuste preestablecido Combinar PDF para obtener un único PDF, o sobre PDF para obtener un PDF por imagen. De forma predeterminada, cada página toma el tamaño de su imagen.`],
  [`One ICO covers everything Windows needs for desktop, Explorer and taskbar icons, and it works as a website favicon too. Start from a square PNG of at least 256×256 px for the sharpest result.`,
    `Un solo ICO cubre todo lo que Windows necesita para los iconos del escritorio, el Explorador y la barra de tareas, y también sirve como favicon de un sitio web. Parte de un PNG cuadrado de al menos 256×256 px para obtener el resultado más nítido.`],
  [`Making a Mac app icon on Windows usually needs extra tools; Filee turns a PNG into an ICNS file directly. Use a square 1024×1024 px PNG so the Retina sizes stay sharp.`,
    `Crear un icono de app para Mac en Windows suele requerir herramientas adicionales; Filee convierte un PNG en un archivo ICNS directamente. Usa un PNG cuadrado de 1024×1024 px para que los tamaños Retina se vean nítidos.`],
  [`Share a Photoshop design with people who don't have Photoshop: the PNG shows the image as saved, with the visible layers combined and transparency kept. PNG can't store layers, so keep the PSD for editing.`,
    `Comparte un diseño de Photoshop con quien no tiene Photoshop: el PNG muestra la imagen tal como se guardó, con las capas visibles combinadas y la transparencia conservada. PNG no guarda capas, así que conserva el PSD para editar.`],
  [`Filee reads the RAW files of Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One and more, and develops them with default settings. It's the quick way to get shareable JPGs from a shoot; for creative editing, use a RAW editor first.`,
    `Filee lee los archivos RAW de Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One y más, y los revela con los ajustes predeterminados. Es la forma rápida de sacar JPG para compartir de una sesión de fotos; para una edición creativa, usa antes un editor RAW.`],
  [`Drop a whole memory card's worth of CR2 files at once: Filee converts them in parallel and saves each JPG next to its RAW file. Newer Canon cameras write CR3, which Filee reads as well.`,
    `Suelta de una vez todos los CR2 de una tarjeta de memoria: Filee los convierte en paralelo y guarda cada JPG junto a su archivo RAW. Las cámaras Canon más nuevas escriben CR3, que Filee también lee.`],
  [`NEF files are too large and too unusual to send as they are. As JPG they become small, universally viewable photos; use JPG 70 % or a half-size preset for messaging apps. Nikon's NRW files from Coolpix cameras work the same way.`,
    `Los archivos NEF son demasiado grandes y poco habituales para enviarlos tal cual. En JPG se convierten en fotos pequeñas que cualquiera puede ver; para apps de mensajería usa JPG 70 % o el ajuste preestablecido Reducir 50 %. Los archivos NRW de las cámaras Nikon Coolpix funcionan igual.`],

  // Conversion guides: vector
  [`Many apps, slide decks and upload forms don't accept SVG. Filee renders the vector drawing to a PNG with transparency; compressed SVGZ files work too.`,
    `Muchas aplicaciones, presentaciones y formularios de subida no aceptan SVG. Filee renderiza el dibujo vectorial a un PNG con transparencia; también funcionan los archivos SVGZ comprimidos.`],
  [`SVG to PDF stays vector: lines and text remain sharp at any zoom and in print, and the file stays small. Handy for sending logos and diagrams to a print shop or putting them into documents.`,
    `De SVG a PDF todo sigue siendo vectorial: las líneas y el texto se mantienen nítidos con cualquier zoom y al imprimir, y el archivo sigue siendo pequeño. Útil para enviar logotipos y diagramas a una imprenta o incluirlos en documentos.`],
  [`EPS can only be displayed by a PostScript interpreter; Filee uses Ghostscript for that. The PDF keeps the vector artwork, so it opens anywhere and still prints sharply. PostScript (.ps) files work the same way.`,
    `EPS solo puede mostrarlo un intérprete de PostScript; Filee usa Ghostscript para ello. El PDF conserva el dibujo vectorial, así que se abre en cualquier sitio y se sigue imprimiendo nítido. Los archivos PostScript (.ps) funcionan igual.`],

  // Conversion guides: PDF
  [`Every page becomes its own JPG, so a 10-page PDF gives you 10 images. Handy for chats, slides and social posts that accept images but not PDF.`,
    `Cada página se convierte en su propio JPG, así que un PDF de 10 páginas te da 10 imágenes. Útil para chats, presentaciones y publicaciones en redes sociales que aceptan imágenes pero no PDF.`],
  [`PNG keeps text and lines crisp without JPG artefacts, which suits slides, diagrams, sheet music and pages you want to annotate or put into a presentation.`,
    `PNG mantiene el texto y las líneas nítidos sin los artefactos de JPG, lo que va bien para diapositivas, diagramas, partituras y páginas que quieras anotar o incluir en una presentación.`],
  [`Filee turns the PDF into a Word document with real paragraphs instead of page pictures, so you can fix typos or reuse the text. Complex layouts may need touch-ups, and a scanned PDF that only contains page images has no text to extract.`,
    `Filee convierte el PDF en un documento de Word con párrafos reales en lugar de imágenes de las páginas, para que puedas corregir erratas o reutilizar el texto. Los diseños complejos pueden necesitar retoques, y un PDF escaneado que solo contiene imágenes de páginas no tiene texto que extraer.`],
  [`Filee goes PDF → Word → EPUB on its own, so the text reflows to fit a phone or an e-reader screen. It works best with PDFs that have real text in them. Headings come through as plain paragraphs, and scanned pages have no text to convert.`,
    `Filee hace por sí solo el camino PDF → Word → EPUB, así que el texto se adapta a la pantalla de un móvil o de un lector de libros electrónicos. Funciona mejor con PDF que contienen texto real. Los títulos quedan como párrafos normales, y las páginas escaneadas no tienen texto que convertir.`],
  [`Filee takes the text of the PDF into a Word document, writes it as HWPX and then saves that as HWP, all with built-in engines. It works for PDFs with real text in them. Complex layouts may need touch-ups, and scanned pages have no text to take out.`,
    `Filee pasa el texto del PDF a un documento de Word, lo escribe como HWPX y luego lo guarda como HWP, todo con motores integrados. Funciona con PDF que contienen texto real. Los diseños complejos pueden necesitar retoques, y las páginas escaneadas no tienen texto que extraer.`],
  [`Filee turns the PDF into a Word document first and then into Markdown, keeping paragraphs, headings and bold text where it can tell them apart. Useful for notes, wikis or pasting the text into other tools. Scanned pages have no text to convert.`,
    `Filee convierte primero el PDF en un documento de Word y luego en Markdown, conservando párrafos, títulos y negritas cuando puede distinguirlos. Útil para notas, wikis o para pegar el texto en otras herramientas. Las páginas escaneadas no tienen texto que convertir.`],
  [`Korean offices often need documents in Hangul format. Filee converts the PDF's text into an HWPX file you can open and edit in Hancom Hangul, without Hancom Office for the conversion; turn it into HWP afterwards if a form requires the old format.`,
    `Las oficinas coreanas a menudo piden documentos en formato Hangul. Filee convierte el texto del PDF en un archivo HWPX que puedes abrir y editar en Hancom Hangul, sin necesidad de Hancom Office para la conversión; conviértelo después a HWP si un formulario exige el formato antiguo.`],
  [`Handy when a PDF has to be shown in PowerPoint or added to an existing deck: every page becomes a slide that looks exactly like the PDF, and the page's text waits in the speaker notes. The slides are pictures, so to change the wording convert the PDF to DOCX instead.`,
    `Útil cuando un PDF tiene que mostrarse en PowerPoint o añadirse a una presentación existente: cada página se convierte en una diapositiva idéntica al PDF, y el texto de la página queda en las notas del orador. Las diapositivas son imágenes, así que para cambiar el texto convierte el PDF a DOCX.`],

  // Conversion guides: documents
  [`No Microsoft Word or LibreOffice needed: Filee reads the DOCX itself and lays out the pages with headers, footers, tables and pictures. Drop several documents on the merge preset to combine them into one PDF.`,
    `No necesitas Microsoft Word ni LibreOffice: Filee lee el DOCX por sí mismo y compone las páginas con encabezados, pies de página, tablas e imágenes. Suelta varios documentos sobre el ajuste preestablecido Combinar PDF para unirlos en un solo PDF.`],
  [`Old Word 97–2003 documents from archives, official forms or legacy systems become PDFs that open anywhere. The same engine also converts ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord and Apple Pages files.`,
    `Los documentos antiguos de Word 97–2003 de archivos, formularios oficiales o sistemas heredados se convierten en PDF que se abren en cualquier sitio. El mismo motor convierte también archivos ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord y Apple Pages.`],
  [`Save e-mails as PDF for records, invoices or legal files: the PDF shows the sender, recipients, date, subject and message, and it opens anywhere without a mail app.`,
    `Guarda correos como PDF para tus registros, facturas o documentación legal: el PDF muestra el remitente, los destinatarios, la fecha, el asunto y el mensaje, y se abre en cualquier sitio sin una aplicación de correo.`],

  // Conversion guides: HWP
  [`Filee renders HWP pages with rhwp, an open-source Hangul engine, so neither Hancom Office nor its approval dialog is involved. Useful for sending Korean documents to people who can't open HWP.`,
    `Filee renderiza las páginas HWP con rhwp, un motor Hangul de código abierto, así que no intervienen ni Hancom Office ni su ventana de aprobación. Útil para enviar documentos coreanos a quien no puede abrir HWP.`],
  [`Turn a Hangul document into a Word file that colleagues abroad can edit. Text, paragraphs and tables are carried over; layouts with many floating objects are worth a quick check in Word.`,
    `Convierte un documento de Hangul en un archivo de Word que tus compañeros en el extranjero puedan editar. Se trasladan el texto, los párrafos y las tablas; conviene revisar rápidamente en Word los diseños con muchos objetos flotantes.`],
  [`HWPX, the newer XML-based Hangul format, is converted like HWP: the built-in rhwp engine lays out the pages, fully offline. Handy for archiving HWPX forms from public institutions as PDF.`,
    `HWPX, el formato Hangul más reciente basado en XML, se convierte igual que HWP: el motor integrado rhwp compone las páginas, totalmente sin conexión. Útil para archivar como PDF los formularios HWPX de instituciones públicas.`],
  [`Some systems and newer workflows accept only HWPX. Filee converts binary HWP to HWPX with rhwp, without Hancom Office, and converts a whole batch of old documents in one go.`,
    `Algunos sistemas y flujos de trabajo nuevos solo aceptan HWPX. Filee convierte el HWP binario a HWPX con rhwp, sin Hancom Office, y convierte un lote entero de documentos antiguos de una vez.`],
  [`Older versions of Hangul and some submission portals still expect .hwp. Filee converts HWPX back to HWP with rhwp, so you don't have to open and re-save each file in Hangul.`,
    `Las versiones antiguas de Hangul y algunos portales de presentación todavía piden .hwp. Filee vuelve a convertir HWPX a HWP con rhwp, así que no tienes que abrir y volver a guardar cada archivo en Hangul.`],
  [`Filee's own HWPX writer carries the Word layout over: page size and margins, headers and footers with page numbers, tables with merged cells, borders and shading, text boxes, shapes and pictures. Every file it writes is checked with three independent HWPX readers in the tests.`,
    `El escritor de HWPX propio de Filee traslada el diseño de Word: tamaño de página y márgenes, encabezados y pies de página con números de página, tablas con celdas combinadas, bordes y sombreado, cuadros de texto, formas e imágenes. Cada archivo que escribe se comprueba en las pruebas con tres lectores de HWPX independientes.`],
  [`For offices and forms that still ask for .hwp. Filee writes the Word document as HWPX with its own writer and converts that to HWP with rhwp, both built in, so Hancom Office isn't needed for the conversion.`,
    `Para oficinas y formularios que todavía piden .hwp. Filee escribe el documento de Word como HWPX con su propio escritor y lo convierte a HWP con rhwp, ambos integrados, así que no hace falta Hancom Office para la conversión.`],
  [`Each page of the Word document becomes a JPG (Filee lays the document out as a PDF first), handy for posting a page online or sending a quick preview. Word isn't needed.`,
    `Cada página del documento de Word se convierte en un JPG (Filee compone primero el documento como PDF), útil para publicar una página en internet o enviar una vista previa rápida. No hace falta Word.`],

  // Conversion guides: spreadsheets
  [`Each visible sheet becomes its own section, with number formats, fonts, fills, borders and merged cells as Excel shows them. Wide sheets are scaled to the page width like Excel's "Fit all columns on one page", and frozen header rows repeat on every page.`,
    `Cada hoja visible se convierte en su propia sección, con los formatos de número, fuentes, rellenos, bordes y celdas combinadas tal como los muestra Excel. Las hojas anchas se escalan al ancho de la página como la opción de Excel «Ajustar todas las columnas en una página», y las filas de encabezado inmovilizadas se repiten en cada página.`],
  [`CSV holds a single table, so Filee writes one CSV per sheet. Cells are exported as values, ready for databases, scripts and import forms.`,
    `CSV contiene una sola tabla, así que Filee escribe un CSV por hoja. Las celdas se exportan como valores, listas para bases de datos, scripts y formularios de importación.`],
  [`An XLSX workbook can hold the formatting, formulas and extra sheets that CSV can't. Select all your CSV exports and drop them at once to get one workbook per file, without Excel's import dialog.`,
    `Un libro XLSX puede contener el formato, las fórmulas y las hojas adicionales que CSV no admite. Selecciona todas tus exportaciones CSV y suéltalas a la vez para obtener un libro por archivo, sin el cuadro de importación de Excel.`],
  [`Upgrade old Excel 97–2003 workbooks without Excel or LibreOffice: the conversion is built in. XLSX files are usually smaller, can't carry macros and open in every current spreadsheet app.`,
    `Actualiza libros antiguos de Excel 97–2003 sin Excel ni LibreOffice: la conversión está integrada. Los archivos XLSX suelen ser más pequeños, no pueden llevar macros y se abren en cualquier aplicación de hojas de cálculo actual.`],

  // Conversion guides: presentations
  [`Each slide becomes one PDF page at the slide's size, with text, shapes, pictures, tables and the master design. Handy for handing out decks or uploading them where PowerPoint files aren't accepted. Animations and speaker notes aren't part of the PDF.`,
    `Cada diapositiva se convierte en una página PDF del tamaño de la diapositiva, con texto, formas, imágenes, tablas y el diseño del patrón. Útil para repartir presentaciones o subirlas donde no se aceptan archivos de PowerPoint. Las animaciones y las notas del orador no forman parte del PDF.`],
  [`Old PowerPoint 97–2003 decks become PDFs that anyone can open, print or upload. Keynote (.key), ODP and WPS (DPS) presentations are converted the same way.`,
    `Las presentaciones antiguas de PowerPoint 97–2003 se convierten en PDF que cualquiera puede abrir, imprimir o subir. Las presentaciones de Keynote (.key), ODP y WPS (DPS) se convierten de la misma forma.`],
  [`Every slide becomes a JPG, ready for social posts, thumbnails, chat messages or a video editor. Choose PNG instead if the slides have lots of small text.`,
    `Cada diapositiva se convierte en un JPG, listo para redes sociales, miniaturas, mensajes de chat o un editor de vídeo. Elige PNG si las diapositivas tienen mucho texto pequeño.`],

  // Conversion guides: text
  [`Headings, lists (including task lists), tables, code, quotes, links, images, footnotes and math are laid out on A4 pages, without Pandoc, LaTeX or a browser. A quick way to share notes and README files with people who don't read Markdown.`,
    `Los títulos, las listas (incluidas las de tareas), las tablas, el código, las citas, los enlaces, las imágenes, las notas al pie y las fórmulas se componen en páginas A4, sin Pandoc, LaTeX ni navegador. Una forma rápida de compartir notas y archivos README con quien no lee Markdown.`],
  [`Built in, no Pandoc needed. Headings, lists, tables, links and footnotes carry over, so you can keep editing and restyling the document in Word.`,
    `Integrado, sin necesidad de Pandoc. Se trasladan los títulos, las listas, las tablas, los enlaces y las notas al pie, así que puedes seguir editando el documento y cambiando sus estilos en Word.`],
  [`Plain text becomes a clean A4 PDF with one paragraph per line. Filee recognises UTF-8 and UTF-16 as well as legacy Korean (CP949) text files, so old logs and notes don't turn into garbled characters.`,
    `El texto sin formato se convierte en un PDF A4 limpio con un párrafo por línea. Filee reconoce UTF-8 y UTF-16, así como los archivos de texto coreanos antiguos (CP949), para que los registros y las notas antiguos no se conviertan en caracteres ilegibles.`],
  [`Save a web page or an HTML report as a PDF that looks the same everywhere and can be archived or printed. Filee converts .html files saved on your PC, and several of them can be merged into one PDF.`,
    `Guarda una página web o un informe HTML como un PDF que se ve igual en todas partes y que se puede archivar o imprimir. Filee convierte archivos .html guardados en tu PC, y se pueden combinar varios en un solo PDF.`],

  // Conversion guides: e-books
  [`A PDF keeps a fixed page layout, which is handy for printing an e-book, reading it on a PC or sending it to a device without an EPUB reader.`,
    `Un PDF mantiene un diseño de página fijo, algo útil para imprimir un libro electrónico, leerlo en un PC o enviarlo a un dispositivo sin lector de EPUB.`],
  [`Move an old Kindle/Mobipocket library to EPUB so it opens in Apple Books, Google Play Books, Kobo and most reader apps. This direction is built in, so Calibre isn't needed.`,
    `Pasa una biblioteca antigua de Kindle/Mobipocket a EPUB para abrirla en Apple Books, Google Play Libros, Kobo y la mayoría de apps de lectura. Esta dirección está integrada, así que no hace falta Calibre.`],
  [`The e-book tool Calibre writes the MOBI and AZW3 files. Current Kindles also accept EPUB through Send to Kindle, so MOBI is mainly useful for older Kindle devices and apps.`,
    `Los archivos MOBI y AZW3 los escribe Calibre, la herramienta de libros electrónicos. Los Kindle actuales también aceptan EPUB mediante Send to Kindle, así que MOBI es útil sobre todo para dispositivos y apps de Kindle antiguos.`],

  // Conversion guides: video
  [`Save the soundtrack of a lecture, concert or interview as an MP3 that plays everywhere: in the car, on an old player or in a transcription tool.`,
    `Guarda el sonido de una clase, un concierto o una entrevista como un MP3 que se reproduce en todas partes: en el coche, en un reproductor antiguo o en una herramienta de transcripción.`],
  [`iPhone and Mac videos are MOV files. As MP4 they play on Android phones, smart TVs, older Windows apps and upload forms that reject MOV. The video and sound usually fit MP4 as they are, so Filee only rewraps them: no quality lost, HDR kept, done in seconds. The MP4 720p preset shrinks 4K clips for sharing.`,
    `Los vídeos del iPhone y del Mac son archivos MOV. En MP4 se reproducen en móviles Android, smart TV, aplicaciones antiguas de Windows y formularios de subida que rechazan MOV. El vídeo y el sonido suelen caber en MP4 tal como están, así que Filee solo los cambia de contenedor: sin pérdida de calidad, con HDR conservado y listo en segundos. El ajuste preestablecido MP4 720p reduce los clips 4K para compartirlos.`],
  [`MKV recordings, for example from OBS, often won't import into video editors or play on TVs, while MP4 is accepted almost everywhere. The conversion runs locally, so long recordings never have to be uploaded.`,
    `Las grabaciones MKV, por ejemplo de OBS, a menudo no se pueden importar en editores de vídeo ni reproducir en televisores, mientras que MP4 se acepta casi en todas partes. La conversión es local, así que las grabaciones largas nunca tienen que subirse.`],
  [`Screen recordings and videos saved from the browser are often WebM, which many video editors, older players and messaging apps handle poorly. MP4 plays almost everywhere, and a whole batch of clips converts at once.`,
    `Las grabaciones de pantalla y los vídeos guardados desde el navegador suelen ser WebM, que muchos editores de vídeo, reproductores antiguos y apps de mensajería manejan mal. MP4 se reproduce casi en todas partes, y un lote entero de clips se convierte de una vez.`],
  [`Turn a short clip into an animated GIF for chats, documentation or bug reports. Keep it short: GIF stores every frame as a 256-colour image, so long or high-resolution videos make very large files.`,
    `Convierte un clip corto en un GIF animado para chats, documentación o informes de errores. Que sea corto: GIF guarda cada fotograma como una imagen de 256 colores, así que los vídeos largos o de alta resolución generan archivos muy grandes.`],
  [`A video dropped on JPG gives one still picture. To pick a thumbnail or go through a clip frame by frame, use the Extract frames (JPG) preset: the pictures land in a folder next to the video, every frame or every Nth. A video that would give more than 100,000 pictures or fill the disk is refused before it starts.`,
    `Un vídeo soltado sobre JPG da una sola imagen fija. Para elegir una miniatura o recorrer un clip fotograma a fotograma, usa el ajuste preestablecido Extraer fotogramas (JPG): las imágenes van a una carpeta junto al vídeo, cada fotograma o uno de cada N. Un vídeo que generaría más de 100 000 imágenes o llenaría el disco se rechaza antes de empezar.`],
  [`AVI files from old camcorders and cameras are large and often use codecs that phones and TVs no longer play. An MP4 with modern compression is usually much smaller and plays everywhere.`,
    `Los archivos AVI de videocámaras y cámaras antiguas son grandes y a menudo usan códecs que los móviles y televisores ya no reproducen. Un MP4 con compresión moderna suele ser mucho más pequeño y se reproduce en todas partes.`],

  // Conversion guides: audio
  [`A WAV recording takes about 10 MB per minute; as MP3 it needs a fraction of that and still plays on every device.`,
    `Una grabación WAV ocupa unos 10 MB por minuto; en MP3 necesita una fracción de eso y sigue reproduciéndose en cualquier dispositivo.`],
  [`Keep your lossless FLAC library at home and put MP3 copies on the phone, a USB stick for the car or an older player that doesn't play FLAC. Whole albums convert in one go.`,
    `Guarda tu biblioteca FLAC sin pérdida en casa y pon copias en MP3 en el móvil, en un USB para el coche o en un reproductor antiguo que no lee FLAC. Los álbumes enteros se convierten de una vez.`],
  [`iPhone voice memos, DRM-free iTunes downloads and many recorders produce M4A. MP3 is accepted by every player, car stereo and upload form.`,
    `Las notas de voz del iPhone, las descargas de iTunes sin DRM y muchas grabadoras generan M4A. MP3 lo acepta cualquier reproductor, autorradio y formulario de subida.`],

  // Conversion guides: archives
  [`Repack RAR archives as ZIP for people, upload forms and systems that only accept ZIP. WinRAR isn't needed, neither to read the RAR nor to write the ZIP.`,
    `Vuelve a empaquetar archivos RAR como ZIP para personas, formularios de subida y sistemas que solo aceptan ZIP. No hace falta WinRAR, ni para leer el RAR ni para escribir el ZIP.`],
  [`7Z often compresses better, but ZIP opens on any computer or phone without extra software. Convert when you send an archive to someone who doesn't have 7-Zip.`,
    `7Z suele comprimir mejor, pero ZIP se abre en cualquier ordenador o móvil sin software adicional. Conviértelo cuando envíes un archivo comprimido a alguien que no tiene 7-Zip.`],

  // Conversion guides: CAD
  [`Send drawings to clients, site teams or print shops who don't have AutoCAD: a PDF opens on any PC or phone. Several drawings can be merged into one PDF.`,
    `Envía planos a clientes, equipos de obra o imprentas que no tienen AutoCAD: un PDF se abre en cualquier PC o móvil. Se pueden combinar varios planos en un solo PDF.`],
  [`DXF files from CAD programs, laser-cutting jobs or design exchanges become PDFs anyone can open and print. SVG and PNG are available too, for example for web previews.`,
    `Los archivos DXF de programas CAD, trabajos de corte láser o intercambios de diseño se convierten en PDF que cualquiera puede abrir e imprimir. También hay SVG y PNG, por ejemplo para vistas previas en la web.`],
  [`DXF is the interchange format that laser cutters, CNC software and most CAD programs read. Converting DWG to DXF lets you open AutoCAD drawings in those tools, and DXF back to DWG works too.`,
    `DXF es el formato de intercambio que leen las cortadoras láser, el software CNC y la mayoría de programas CAD. Convertir DWG a DXF te permite abrir planos de AutoCAD en esas herramientas, y de DXF a DWG también funciona.`],

  // Conversion guides: fonts
  [`Self-host a font on your website: WOFF2 is the compressed web font format every modern browser supports, typically about 30 % smaller than WOFF. Check that the font's license allows web embedding.`,
    `Aloja una tipografía en tu propio sitio web: WOFF2 es el formato comprimido de tipografías web que admite cualquier navegador moderno, normalmente un 30 % más pequeño que WOFF. Comprueba que la licencia de la tipografía permite incrustarla en la web.`],
  [`Some older programs, cutting and embroidery machines and game engines only accept TrueType fonts. Convert a whole OTF font family to TTF in one go, without a font editor.`,
    `Algunos programas antiguos, máquinas de corte y bordado y motores de videojuegos solo aceptan tipografías TrueType. Convierte una familia OTF entera a TTF de una vez, sin editor de tipografías.`],

  // Conversion guides: tracing and SVG → CAD
  [`Use Line art to SVG for logos, signatures and scans: the ink becomes one black shape on a transparent background. Trace to SVG keeps up to 64 colours for icons and illustrations. Photos come out as flat patches, so tracing suits drawings best.`,
    `Usa Líneas a SVG para logotipos, firmas y escaneos: la tinta se convierte en una única forma negra sobre fondo transparente. Trazar a SVG conserva hasta 64 colores para iconos e ilustraciones. Las fotos quedan como manchas planas, así que el trazado funciona mejor con dibujos.`],
  [`A JPG of a logo or a scanned sketch becomes an SVG that stays sharp at any size, ready for a cutting plotter, a website or a print shop. JPG noise turns into specks, so lower the Detail setting in the preset if the result looks busy.`,
    `Un JPG de un logotipo o un boceto escaneado se convierte en un SVG que se mantiene nítido a cualquier tamaño, listo para un plóter de corte, un sitio web o una imprenta. El ruido del JPG se convierte en motas, así que baja el «Detalle» en el ajuste preestablecido si el resultado se ve recargado.`],
  [`Laser cutters, CNC software and CAD programs read DXF. Filee writes the SVG's outlines in millimetres, so a shape 100 mm wide stays 100 mm. Curves become fine polylines. Fills, images and filters are left out.`,
    `Las cortadoras láser, el software CNC y los programas CAD leen DXF. Filee escribe los contornos del SVG en milímetros, así que una forma de 100 mm de ancho sigue midiendo 100 mm. Las curvas se convierten en polilíneas finas. Los rellenos, las imágenes y los filtros se omiten.`],

  // Conversion guides: e-mail
  [`E-mails dragged out of Outlook are MSG files that only Outlook opens. As PDF they keep the sender, recipients, date, subject and message, and open anywhere. Outlook isn't needed.`,
    `Los correos arrastrados fuera de Outlook son archivos MSG que solo abre Outlook. En PDF conservan el remitente, los destinatarios, la fecha, el asunto y el mensaje, y se abren en cualquier sitio. No hace falta Outlook.`],

  // Conversion guides: data
  [`YAML is easier to read and edit by hand, which is why config files use it. Keys keep their order, and text that would read back as a number or true/false is quoted.`,
    `YAML es más fácil de leer y editar a mano, por eso lo usan los archivos de configuración. Las claves conservan su orden, y el texto que al volver a leerse pasaría a ser un número o true/false se pone entre comillas.`],
  [`Turn a config file into JSON for an API, a script or a tool that only reads JSON. Anchors and aliases are resolved, and a file with several documents becomes one array. Comments are dropped, since JSON has none.`,
    `Convierte un archivo de configuración a JSON para una API, un script o una herramienta que solo lee JSON. Las anclas y los alias se resuelven, y un archivo con varios documentos se convierte en una sola matriz. Los comentarios se descartan, ya que JSON no los admite.`],
  [`A JSON list of records becomes a table you can open in Excel: one row per record, one column per key. A wrapper like {"users": […]} is looked through. Data that isn't a table stops with a message instead of a broken file.`,
    `Una lista de registros en JSON se convierte en una tabla que puedes abrir en Excel: una fila por registro, una columna por clave. Un objeto envolvente como {"users": […]} se desempaqueta. Los datos que no son una tabla se detienen con un mensaje en lugar de dar un archivo dañado.`],
  [`Get an address book into Excel or a mailing tool: one row per contact with name, organization, email, phone, address and birthday. Contacts from old Korean phones in CP949 are read correctly.`,
    `Lleva una libreta de direcciones a Excel o a una herramienta de envío de correos: una fila por contacto con nombre, organización, correo electrónico, teléfono, dirección y cumpleaños. Los contactos de móviles coreanos antiguos en CP949 se leen correctamente.`],

  // Conversion guides: subtitles
  [`Web players and online course platforms want WebVTT. Timing, line breaks and italics come across, and no engine is needed.`,
    `Los reproductores web y las plataformas de cursos en línea piden WebVTT. Se trasladan los tiempos, los saltos de línea y la cursiva, y no hace falta ningún motor.`],
  [`Many players, TVs and editors don't read SMI, and old Korean SMI files often show as broken text. Filee detects CP949, picks the language with the most lines and saves a clean UTF-8 SRT.`,
    `Muchos reproductores, televisores y editores no leen SMI, y los archivos SMI coreanos antiguos suelen mostrarse como texto ilegible. Filee detecta CP949, elige el idioma con más líneas y guarda un SRT limpio en UTF-8.`],
  [`When a TV, a phone or a video site refuses styled ASS subtitles, plain SRT works. Bold, italics, underline and colours are kept; positions, fonts and effects are dropped.`,
    `Cuando un televisor, un móvil o una web de vídeos rechaza los subtítulos ASS con estilos, un SRT sencillo funciona. Se conservan la negrita, la cursiva, el subrayado y los colores; las posiciones, las fuentes y los efectos se descartan.`],
  [`Take the subtitles out of a film to edit or translate them. The first text subtitle track is saved as SRT; picture-based subtitles (DVD, Blu-ray) can't be turned into text. Needs the free FFmpeg engine.`,
    `Saca los subtítulos de una película para editarlos o traducirlos. La primera pista de subtítulos de texto se guarda como SRT; los subtítulos basados en imágenes (DVD, Blu-ray) no se pueden convertir en texto. Necesita el motor gratuito FFmpeg.`],

  // Conversion guides: 3D models
  [`Open a print file in a 3D program that prefers OBJ. STL has no units, so Filee reads it as millimetres and writes OBJ in millimetres too, with Y pointing up like most 3D programs.`,
    `Abre un archivo de impresión en un programa 3D que prefiere OBJ. STL no tiene unidades, así que Filee lo lee en milímetros y escribe el OBJ también en milímetros, con el eje Y hacia arriba, como la mayoría de programas 3D.`],
  [`Slicers for 3D printers take STL. Faces of any shape are split into triangles, and Y-up becomes Z-up, so an upright model stands on the print bed. STL keeps only the shape, so colours and textures stay in the OBJ.`,
    `Los laminadores de las impresoras 3D usan STL. Las caras de cualquier forma se dividen en triángulos y el eje Y hacia arriba pasa a ser Z hacia arriba, así que un modelo de pie se apoya en la cama de impresión. STL solo guarda la forma, así que los colores y las texturas se quedan en el OBJ.`],
  [`Bring a model from the web or a game engine into a program that reads OBJ. The .mtl file and the textures are written next to the .obj, so keep them together.`,
    `Lleva un modelo de la web o de un motor de videojuegos a un programa que lee OBJ. El archivo .mtl y las texturas se escriben junto al .obj, así que mantenlos juntos.`],

  // FAQ
  [`Is Filee really free?`,
    `¿Filee es realmente gratis?`],
  [`Yes. Filee is free and open source under the MIT license: no ads, no watermarks, no account, no trial and no file-count or file-size limits of its own.`,
    `Sí. Filee es gratuito y de código abierto con licencia MIT: sin anuncios, sin marcas de agua, sin cuenta, sin periodo de prueba y sin límites propios de número ni de tamaño de archivos.`],
  [`Does it work offline? Are my files uploaded?`,
    `¿Funciona sin conexión? ¿Se suben mis archivos?`],
  [`Every conversion runs on your own PC and files are never uploaded. The internet is only used to download an optional engine or check for updates, so confidential documents, photos and recordings stay on your computer.`,
    `Todas las conversiones se hacen en tu propio PC y los archivos nunca se suben. Internet solo se usa para descargar un motor opcional o buscar actualizaciones, así que los documentos confidenciales, las fotos y las grabaciones se quedan en tu ordenador.`],
  [`Which file formats does Filee support?`,
    `¿Qué formatos de archivo admite Filee?`],
  [`Filee reads {formatTotal} file formats in {categoryCount} categories: {categoryList}. {builtinTotal} of them work right after install; the others use a free optional engine. The format catalog lists every format and what it converts to.`,
    `Filee lee {formatTotal|one:# formato|other:# formatos} de archivo en {categoryCount|one:# categoría|other:# categorías}: {categoryList}. De ellos, {builtinTotal|one:# funciona|other:# funcionan} nada más instalarlo; los demás usan un motor opcional gratuito. El catálogo de formatos enumera cada formato y a qué se convierte.`],
  [`Do I need Microsoft Office, Hancom Office or LibreOffice?`,
    `¿Necesito Microsoft Office, Hancom Office o LibreOffice?`],
  [`No. Word, Excel and PowerPoint files (DOCX, XLSX, XLS, CSV, PPTX) and Korean HWP/HWPX documents are converted by engines built into Filee. Filee doesn't use Office or Hancom Office even when they are installed; LibreOffice is only an optional in-app download for older formats such as DOC, PPT, ODT and RTF.`,
    `No. Los archivos de Word, Excel y PowerPoint (DOCX, XLSX, XLS, CSV, PPTX) y los documentos coreanos HWP/HWPX los convierten motores integrados en Filee. Filee no usa Office ni Hancom Office aunque estén instalados; LibreOffice es solo una descarga opcional dentro de la aplicación para formatos antiguos como DOC, PPT, ODT y RTF.`],
  [`What are the optional engines?`,
    `¿Qué son los motores opcionales?`],
  [`Large engines are not in the installer. Tick them on the installer's engine page, or download them inside Filee whenever you need them: {engineDetails}. They are saved in Filee's own folder and can be removed at any time, and the app shows their versions, download speed and time left. If FFmpeg, calibre, Pandoc, Ghostscript or LibreOffice is already on your PC (on the PATH, Scoop included, or in Program Files), Filee uses it and skips the download, and says when that copy is older than the version it is tested with. Settings → Engines → Use my copy picks a specific one.`,
    `Los motores grandes no van en el instalador. Márcalos en la página de motores del instalador o descárgalos dentro de Filee cuando los necesites: {engineDetails}. Se guardan en la carpeta propia de Filee y se pueden quitar en cualquier momento, y la aplicación muestra sus versiones, la velocidad de descarga y el tiempo restante. Si FFmpeg, calibre, Pandoc, Ghostscript o LibreOffice ya están en tu PC (en el PATH, Scoop incluido, o en Program Files), Filee los usa y se salta la descarga, y te avisa cuando esa copia es más antigua que la versión con la que se ha probado. En Ajustes → Motores → Usar mi copia puedes elegir una concreta.`],
  [`Does installing Filee need administrator rights?`,
    `¿Instalar Filee requiere permisos de administrador?`],
  [`Only once, while installing. The installer puts Filee in Program Files for all users and, on Windows 11, adds “Convert with Filee” to the top of the File Explorer menu. Filee itself then runs as your normal user. For silent installs, run the installer with /VERYSILENT /SUPPRESSMSGBOXES. If you can't install programs, use the portable ZIP: unzip it anywhere and run Filee.exe.`,
    `Solo una vez, durante la instalación. El instalador pone Filee en Program Files para todos los usuarios y, en Windows 11, añade «Convertir con Filee» a la parte superior del menú del Explorador de archivos. Después, Filee se ejecuta con tu usuario normal. Para una instalación silenciosa, ejecuta el instalador con /VERYSILENT /SUPPRESSMSGBOXES. Si no puedes instalar programas, usa el ZIP portátil: descomprímelo en cualquier sitio y ejecuta Filee.exe.`],
  [`Can I convert many files at once?`,
    `¿Puedo convertir muchos archivos a la vez?`],
  [`Yes. Select as many files as you like and drop them once: Filee converts them in parallel, a failed file never stops the others, and presets can merge everything into one PDF or pack it into one ZIP.`,
    `Sí. Selecciona todos los archivos que quieras y suéltalos de una vez: Filee los convierte en paralelo, un archivo que falla nunca detiene a los demás, y los ajustes preestablecidos pueden combinarlo todo en un PDF o empaquetarlo en un ZIP.`],
  [`Can I convert from the Windows 11 right-click menu?`,
    `¿Puedo convertir desde el menú contextual de Windows 11?`],
  [`Yes. Right-click files in File Explorer and choose "Convert with Filee". On Windows 11 you can also put it in the top-level menu, without "Show more options": click "Add to the main menu" in Settings → General once and approve the administrator prompt. Send To, a keyboard shortcut and the drop zone in the main window work too.`,
    `Sí. Haz clic derecho sobre los archivos en el Explorador de archivos y elige «Convertir con Filee». En Windows 11 también puedes ponerlo en el menú principal, sin «Mostrar más opciones»: haz clic una vez en «Añadir al menú principal» en Ajustes → General y acepta la solicitud de administrador. También funcionan Enviar a, un atajo de teclado y la zona de suelta de la ventana principal.`],
  [`Can Filee convert from the command line or automatically?`,
    `¿Puede Filee convertir desde la línea de comandos o automáticamente?`],
  [`Yes. Setup can add the filee command to PATH: filee convert *.heic --to jpg converts files, wildcards and folders with your presets, prints JSON for scripts and returns exit codes. Watch folders automatically convert the files that land in a folder and can move the originals aside. Set them up on the Watch folders page in the app or with filee watch in a terminal.`,
    `Sí. El instalador puede añadir el comando filee al PATH: filee convert *.heic --to jpg convierte archivos, comodines y carpetas con tus ajustes preestablecidos, imprime JSON para scripts y devuelve códigos de salida. Las carpetas supervisadas convierten automáticamente los archivos que llegan a una carpeta y pueden apartar los originales. Configúralas en la página Carpetas supervisadas de la aplicación o con filee watch en un terminal.`],
  [`How do I convert a file, for example HEIC to JPG?`,
    `¿Cómo convierto un archivo, por ejemplo de HEIC a JPG?`],
  [`Select the files in File Explorer, hold Ctrl (or the key you chose) and drag them. A donut of formats opens at the cursor: drop the files on JPG and the new files appear next to the originals. There are step-by-step guides for the most common conversions.`,
    `Selecciona los archivos en el Explorador de archivos, mantén pulsado Ctrl (o la tecla que hayas elegido) y arrástralos. En el cursor se abre un menú circular de formatos: suelta los archivos sobre JPG y los nuevos archivos aparecen junto a los originales. Hay guías paso a paso para las conversiones más habituales.`],
  [`Why use Filee instead of an online converter?`,
    `¿Por qué usar Filee en lugar de un conversor en línea?`],
  [`Online converters upload your files to someone else's server, often limit file size and count, and depend on a fast connection. Filee converts on your PC: private files stay private, large videos and hundreds of files are no problem, and it works without internet, for free and without ads.`,
    `Los conversores en línea suben tus archivos al servidor de otra persona, a menudo limitan el tamaño y el número de archivos y dependen de una conexión rápida. Filee convierte en tu PC: los archivos privados siguen siendo privados, los vídeos grandes y los cientos de archivos no son ningún problema, y funciona sin internet, gratis y sin anuncios.`],
  [`Which operating systems are supported?`,
    `¿Qué sistemas operativos son compatibles?`],
  [`Windows 10 and 11 (64-bit) and Linux (x64 and ARM64, Ubuntu 22.04 or later) are full releases. On Linux the drag gesture needs an X11 session; on KDE Plasma with Wayland it is experimental, and on other Wayland desktops the drop zone and the file manager's right-click menu work. macOS 13 or later (Apple silicon and Intel) is a preview: the app isn't notarized yet, so macOS asks you to allow it once under Privacy & Security. Pick your system in the download section.`,
    `Windows 10 y 11 (64 bits) y Linux (x64 y ARM64, Ubuntu 22.04 o posterior) son versiones completas. En Linux, el gesto de arrastre necesita una sesión X11; en KDE Plasma con Wayland es experimental, y en otros escritorios Wayland funcionan la zona de suelta y el menú contextual del gestor de archivos. macOS 13 o posterior (Apple silicon e Intel) es una versión preliminar: la app aún no está notarizada, así que macOS te pide permitirla una vez en Privacidad y seguridad. Elige tu sistema en la sección de descarga.`],
]);
